w=Path(__file__).resolve().parent;read=lambda p:json.loads(p.read_text());a=read(w/'validation-acceptance.json');assert a['passed'];b=read(w/'candidate-build.json');i=read(w/'inputs.json');gib=2**30
s='# Native 128K prefill and decode correctness\n\n'
